 import { MeshPhysicalNodeMaterial, MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, float, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const root = new ctx.THREE.Group();
  const disposables = [];
  const timelines = [];
  const primitiveRefs = [];

  // ----- palette helpers -----
  const ink      = new ctx.THREE.Color('#0b0b10');
  const surface  = new ctx.THREE.Color('#101017');
  const inkMid   = new ctx.THREE.Color('#12121a');
  const paper    = new ctx.THREE.Color('#e8ecf2');
  const accent   = new ctx.THREE.Color('#ff2a38');
  const coolRim  = new ctx.THREE.Color('#9fb0c4');

  // ----- backdrop gradient plane -----
  const backdropGeo = new ctx.THREE.PlaneGeometry(7, 6);
  disposables.push(backdropGeo);

  const bgGrad = mix(
    mix(
      vec3(ink.r, ink.g, ink.b),
      vec3(inkMid.r, inkMid.g, inkMid.b),
      smoothstep(0.0, 0.6, uv().y)
    ),
    vec3(surface.r, surface.g, surface.b),
    smoothstep(0.6, 1.0, uv().y)
  );

  const backdropMat = new MeshBasicNodeMaterial({ side: ctx.THREE.DoubleSide });
  backdropMat.colorNode = bgGrad;
  disposables.push(backdropMat);

  const backdrop = new ctx.THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -2.5;
  root.add(backdrop);

  // ----- glass prism -----
  // equilateral triangle side = 1.2 -> circumradius = side / sqrt(3)
  const side = 1.2;
  const R = side / Math.sqrt(3);
  const prismLen = 1.8;

  const prismGeo = new ctx.THREE.CylinderGeometry(R, R, prismLen, 3);
  prismGeo.rotateX(-Math.PI / 2);          // make length axis horizontal (Z)
  prismGeo.rotateZ(Math.PI / 6);           // orient a flat face
  disposables.push(prismGeo);

  const prismMat = new MeshPhysicalNodeMaterial({
    color: paper,
    metalness: 0,
    roughness: 0.08,
    transmission: 1.0,
    thickness: 0.9,
    ior: 1.55,
    dispersion: 0.18,
    iridescence: 1.0,
    iridescenceIOR: 1.3,
    iridescenceThicknessRange: [120, 480],
    clearcoat: 0.25,
    clearcoatRoughness: 0.1,
    attenuationColor: paper,
    attenuationDistance: 2.5,
    side: ctx.THREE.DoubleSide
  });
  disposables.push(prismMat);

  const prism = new ctx.THREE.Mesh(prismGeo, prismMat);
  prism.rotation.z = 12 * Math.PI / 180;
  prism.rotation.y = 20 * Math.PI / 180;
  root.add(prism);

  // ----- emissive core -----
  const coreGeo = new ctx.THREE.OctahedronGeometry(0.35);
  disposables.push(coreGeo);

  const coreMat = new MeshStandardNodeMaterial({
    color: accent,
    emissive: accent,
    emissiveIntensity: 2.2,
    roughness: 0.4,
    metalness: 0.1
  });
  disposables.push(coreMat);

  const core = new ctx.THREE.Mesh(coreGeo, coreMat);
  root.add(core);

  // ----- lighting -----
  const rimLight = new ctx.THREE.DirectionalLight(coolRim, 1.4);
  rimLight.position.set(-4, 2.5, -5);
  root.add(rimLight);

  // subtle cool fill from front-right
  const fillLight = new ctx.THREE.DirectionalLight(paper, 0.45);
  fillLight.position.set(3, 1, 4);
  root.add(fillLight);

  // ----- caustic streak -----
  const streakGeo = new ctx.THREE.PlaneGeometry(2.4, 0.5);
  streakGeo.rotateX(-Math.PI / 2);
  disposables.push(streakGeo);

  const c1 = new ctx.THREE.Color('#ff2a38');
  const c2 = paper;
  const c3 = coolRim;

  const streakGrad = mix(
    mix(
      vec3(c1.r, c1.g, c1.b),
      vec3(c2.r, c2.g, c2.b),
      smoothstep(0.2, 0.5, uv().x)
    ),
    vec3(c3.r, c3.g, c3.b),
    smoothstep(0.5, 0.8, uv().x)
  );

  const streakMat = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
    side: ctx.THREE.DoubleSide
  });
  streakMat.colorNode = streakGrad;
  streakMat.opacityNode = float(0.35);
  disposables.push(streakMat);

  const streak = new ctx.THREE.Mesh(streakGeo, streakMat);
  streak.position.set(0, -1.1, 0.25);
  root.add(streak);

  // ----- text -----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineCopy = items.find(i => i.role === 'headline')?.text ?? 'Light, machined.';
  const captionCopy  = items.find(i => i.role === 'caption')?.text ?? 'SAPPHIRE OVER DIAL / ZERO DISTORTION';

  const headline = ctx.fontAtlas.createText(headlineCopy, {
    fontSize: 68,
    color: '#e8ecf2',
    align: 'center'
  });
  headline.position.set(0, -1.75, 0.75);
  root.add(headline);

  const caption = ctx.fontAtlas.createText(captionCopy, {
    fontSize: 18,
    color: '#9fb0c4',
    align: 'center',
    letterSpacingPx: 2
  });
  caption.position.set(0, -2.25, 0.75);
  root.add(caption);

  // ----- load entrance animation -----
  const loadTL = gsap.timeline({ delay: 0.1 });
  loadTL.from(prism.position, { y: '-=0.4', duration: 0.8, ease: 'power3.out' }, 0)
        .from(core.position,     { y: '-=0.4', duration: 0.8, ease: 'power3.out' }, 0)
        .from(prism.scale,       { x: 0.95, y: 0.95, z: 0.95, duration: 0.9, ease: 'power4.out' }, 0)
        .from(core.scale,        { x: 0.95, y: 0.95, z: 0.95, duration: 0.9, ease: 'power4.out' }, 0)
        .from(streak.scale,      { x: 0.92, duration: 0.8, ease: 'power2.out' }, 0.15)
        .from(headline.position,  { y: '+=0.2', duration: 0.6, ease: 'power2.out' }, 0.25)
        .from(caption.position,   { y: '+=0.2', duration: 0.6, ease: 'power2.out' }, 0.35);

  timelines.push(loadTL);

  // ----- idle emissive pulse -----
  const idleTL = gsap.timeline({ repeat: -1, yoyo: true, repeatDelay: 0.4 });
  idleTL.to(coreMat, { emissiveIntensity: 1.85, duration: 2.2, ease: 'sine.inOut' });
  timelines.push(idleTL);

  // ----- cinematic primitive: depth-rotate on hover -----
  const primParams = config.cinematicPrimitives?.find(p => p.name === 'depth-rotate')?.params ?? { trigger: 'hover', maxDeg: 10 };
  const depthRot = ctx.primitives['depth-rotate'](root, { trigger: 'hover', ...primParams });
  if (depthRot) primitiveRefs.push(depthRot);

  // ----- event surface & lifecycle -----
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    primitiveRefs.forEach(p => { try { p.cleanup(); } catch (e) {}
